(() => {
 'use strict';const D=window.NastranModeling,$=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(v,n=6)=>Number(v).toLocaleString('ja-JP',{maximumFractionDigits:n});let selected='simple';
 const qrg=p=>`https://documentation-be.hexagon.com/bundle/MSC_Nastran_2020_Quick_Reference_Guide/raw/resource/enus/MSC_Nastran_2020_Quick_Reference_Guide.pdf#page=${p}`;
 document.querySelectorAll('[data-qrg]').forEach(a=>{a.href=qrg(a.dataset.qrg);a.target='_blank';a.rel='noopener';});
 const text=(x,y,s,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}">${esc(s)}</text>`,path=(p,color='#7f99bd',width=2)=>`<path d="${p}" stroke="${color}" stroke-width="${width}" fill="none"/>`,arrow=(x,y,len=55)=>path(`M${x} ${y}v${len}m-7 -12l7 12l7 -12`,'#c77743',3);
 const proj=([x,y,z])=>[95+.45*x+1.5*z,175-2*y-.6*z],pstr=p=>proj(p).join(','),segment=(a,b,color,width)=>path('M'+pstr(a)+'L'+pstr(b),color,width);
 function solidScene(){let s='';const poly=(points,fill)=>`<polygon points="${points.map(pstr).join(' ')}" fill="${fill}" stroke="#7195c9" stroke-width="1.5"/>`;
  s+=poly([[0,-20,15],[1000,-20,15],[1000,20,15],[0,20,15]],'#edf3ff')+poly([[0,20,-15],[1000,20,-15],[1000,20,15],[0,20,15]],'#e3ecfc')+poly([[1000,-20,-15],[1000,20,-15],[1000,20,15],[1000,-20,15]],'#fae9dc');
  for(let x=0;x<=1000;x+=50)s+=segment([x,-20,15],[x,20,15])+segment([x,20,15],[x,20,-15]);
  s+=segment([0,0,15],[1000,0,15])+segment([0,20,0],[1000,20,0])+segment([1000,0,-15],[1000,0,15],'#ba8c70')+segment([1000,-20,0],[1000,20,0],'#ba8c70');
  for(const y of [-10,10])for(const z of [-7.5,7.5]){const [x0,y0]=proj([1000,y,z]);s+=arrow(x0,y0,38);}
  s+=text(330,70,'体積を20×2×2に分ける')+text(350,300,'先端4面に、合計120 N')+text(350,330,'表面の分割を表示');return s;
 }
 function scene(){const m=D.models[selected];let s='';if(selected==='simple'){
  s+=path('M155 75H325M170 55V75M195 55V75M220 55V75M245 55V75M270 55V75M295 55V75','#8da3bf',3)+text(350,42,'動かない相手（グラウンド）');
  s+=path('M240 75V100L222 110L258 128L222 146L258 164L222 182L240 192V216','#315bd0',4);s+='<circle cx="240" cy="222" r="9" fill="#315bd0"/>'+arrow(240,237,55)+text(345,146,'k = 100.8 N/mm','start')+text(345,214,'GRID 1：先端','start')+text(345,263,'−Yへ120 N','start')+text(350,332,'梁全体 → 先端1方向の硬さ');
 }else{
  s+=path('M67 85V260M45 100L67 85M45 130L67 115M45 160L67 145M45 190L67 175M45 220L67 205M45 250L67 235','#8da3bf',3)+text(85,45,'固定');
  if(selected==='standard'){s+=path('M95 175H545','#315bd0',4);for(let i=0;i<11;i++)s+=`<circle cx="${95+45*i}" cy="175" r="5" fill="#315bd0"/>`;s+=arrow(545,185,70)+text(340,105,'10個のCBAR')+text(340,135,'線に断面の性質を持たせる')+text(545,292,'120 N')+text(145,220,'GRID 1')+text(350,330,'節点では、移動と回転を計算');}
  else s+=solidScene();
 }
 $('model-scene').innerHTML=s;$('model-scene').setAttribute('aria-label',m.title+'。'+m.keeps);$('model-scene-note').textContent=m.note;
 }
 function trail(){const a=(card,label=card)=>`<a href="${card==='CELAS2'?'dynamics.html#card-CELAS2':'bulk.html#'+card}">${label}</a>`,s=(label)=>`<span>${label}</span>`,arrow='<i aria-hidden="true">→</i>';let rows;
 if(selected==='simple')rows=[[s('LOAD = 20'),a('FORCE'),a('GRID','GRID 1 / Y')],[a('CELAS2'),s('K = 100.8'),s('固定の相手 = 0')],[s('SPC = 10'),a('SPC1','SPC1 / 13456')]];
 else if(selected==='standard')rows=[[a('CBAR'),s('PID 200'),a('PBAR'),s('MID 300'),a('MAT1')],[s('LOAD = 20'),a('FORCE'),a('GRID','先端GRID 11')],[s('SPC = 10'),a('SPC1','根元GRID 1 / 123456')]];
 else rows=[[a('CHEXA','CHEXA / 20節点'),s('PID 200'),a('PSOLID'),s('MID 300'),a('MAT1')],[s('LOAD = 20'),a('PLOAD4'),s('EID / G1 / G3で面を選ぶ')],[s('SPC = 10'),a('SPC1','根元123 / 全節点456')]];
 $('model-trail').innerHTML=rows.map(r=>'<div>'+r.join(arrow)+'</div>').join('');}
 function fieldURL(card,line,index,label){if(card==='CELAS2')return 'dynamics.html#field-CELAS2-'+line+'-'+index;const key=index===0?(line?'継続行':''):label;return 'bulk.html#'+card+(key?'/'+encodeURIComponent(key):'');}
 function renderRows(){const m=D.models[selected],part=$('model-row-filter').value;let rows=[];if(part==='key'){const seen=new Set();rows=m.rows.filter(r=>{if(!['CELAS2','CBAR','CHEXA','PBAR','PSOLID','MAT1'].includes(r.card))return false;const key=r.card+':'+r.line;if(seen.has(key))return false;seen.add(key);return true;});}else if(part==='nodes')rows=m.rows.filter(r=>r.card==='GRID').slice(0,4);else if(part==='loads')rows=m.rows.filter(r=>['FORCE','PLOAD4'].includes(r.card));else if(part==='param')rows=m.rows.filter(r=>r.card==='PARAM');else{const seen=new Set();rows=m.rows.filter(r=>r.card==='SPC1').filter(r=>{const c=r.values[2];if(seen.has(c))return false;seen.add(c);return true;});}
 $('model-row-note').textContent=`完成入力はBulk ${m.rows.length}行。ここは${rows.length}行を表示しています。代表行の表示を選んだ場合も、保存時には全節点・全要素・全拘束を含みます。各見出しを押すと、その欄の説明へ進みます。`;
 $('model-input-tables').innerHTML=rows.map(r=>{const labels=D.schemas[r.card][r.line];return `<div class="nf-card"><div class="nf-caption"><strong>${r.card}</strong><span>${r.line?'継続行 '+r.line:''}</span></div><div class="nf-scroll" tabindex="0" aria-label="${r.card}の8文字入力表。横スクロールできます"><table class="nf-table"><thead><tr>${labels.map((l,i)=>`<th scope="col"><small>第${i+1}欄</small><span>${i*8+1}–${i*8+8}列</span><b><a href="${fieldURL(r.card,r.line,i,l)}">${esc(l)}</a></b></th>`).join('')}</tr></thead><tbody><tr>${labels.map((_,i)=>{const v=r.text.slice(i*8,i*8+8);return `<td${v.trim()?'':' class="nf-empty"'}>${v.trim()?'<code>'+esc(v)+'</code>':'<span aria-label="8文字分の空欄">空欄</span>'}</td>`;}).join('')}</tr></tbody></table></div></div>`;}).join('');
 }
 function select(id){if(!D.models[id])return;selected=id;const m=D.models[id];$('model-input-picker').value=id;document.querySelectorAll('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===id)));$('model-title').textContent=m.title;$('model-count').textContent=m.nodes.length+'節点 / '+m.elementCount+'要素';$('model-facts').innerHTML='<div><b>知りたいこと</b><p>'+esc(m.goal)+'</p><b>残したもの</b><p>'+esc(m.keeps)+'</p></div><div><b>この模型が表さないもの</b><p>'+esc(m.omits)+'</p></div>';$('model-filename').textContent=m.filename;$('model-case-code').textContent=[...m.executive,...m.control,'BEGIN BULK'].join('\n');$('model-raw').textContent=m.deck;scene();trail();renderRows();}
 document.querySelectorAll('[data-model]').forEach(b=>b.addEventListener('click',()=>location.hash='model-'+b.dataset.model));$('model-input-picker').addEventListener('change',()=>{select($('model-input-picker').value);history.replaceState(null,'','#model-input-'+selected);});$('model-row-filter').addEventListener('change',renderRows);
 function route(){const m=/^#model-(?:(input)-)?(simple|standard|detailed)$/.exec(location.hash);if(m){select(m[2]);(m[1]?$('model-input'):$('model-compare')).scrollIntoView({block:'start'});}}window.addEventListener('hashchange',route);
 function theory(){const load=Number($('model-load').value),x=Number($('model-x').value),p=D.theory(x,load);$('model-x-label').textContent=x+' mm';$('model-theory-values').innerHTML=`<div><small>位置xでのUY</small><strong>${num(p.u,5)}</strong><span>mm · 下向きは負</span></div><div><small>上面の公称応力</small><strong>+${num(p.stressTop,3)}</strong><span>MPa · 引張</span></div><div><small>下面の公称応力</small><strong>${num(p.stressBottom,3)}</strong><span>MPa · 圧縮</span></div>`;
  const px=x=>85+x/1000*535,py=u=>75-u/2.5*170;let s=text(85,35,'UY (mm)','start')+text(620,293,'x (mm)','end');for(const xx of [0,250,500,750,1000])s+=path(`M${px(xx)} 65V250`,'#e0e8f4',1)+text(px(xx),275,xx);for(const u of [0,-.5,-1,-1.5,-2,-2.5])s+=path(`M85 ${py(u)}H620`,'#e0e8f4',1)+text(73,py(u)+6,u,'end');s+=path(Array.from({length:101},(_,i)=>{const xx=i*10;return (i?'L':'M')+px(xx)+','+py(D.theory(xx,load).u);}).join(' '),'#315bd0',3)+`<circle cx="${px(x)}" cy="${py(p.u)}" r="6" fill="#c77743"/>`;$('model-curve').innerHTML=s;
 }
 $('model-load').addEventListener('change',theory);$('model-x').addEventListener('input',theory);
 function endFace(){const nodes=D.models.detailed.nodes.filter(n=>n.x===1000),x=z=>210+6*z,y=v=>160-5*v;let s='';for(const yy of [-20,0,20])s+=path(`M120 ${y(yy)}H300`,'#a9bedc');for(const zz of [-15,0,15])s+=path(`M${x(zz)} 60V260`,'#a9bedc');for(const n of nodes)s+=`<circle cx="${x(n.z)}" cy="${y(n.y)}" r="${n.y===0&&n.z===0?7:4}" fill="${n.y===0&&n.z===0?'#c77743':'#315bd0'}"/>`;s+=text(210,30,'先端面：4面・21節点')+text(210,302,'中央 GRID '+D.models.detailed.tip)+text(210,335,'中心のUYを比較する')+text(50,150,'＋Y')+text(350,150,'＋Z');$('model-end-face').innerHTML=s;$('model-tip-grid').textContent='先端中心 GRID '+D.models.detailed.tip;}
 let timer;function toast(t){$('model-toast').hidden=false;$('model-toast').textContent=t;clearTimeout(timer);timer=setTimeout(()=>$('model-toast').hidden=true,4000);}
 $('save-model').addEventListener('click',()=>{const m=D.models[selected],url=URL.createObjectURL(new Blob([m.deck],{type:'text/plain;charset=us-ascii'})),a=document.createElement('a');a.href=url;a.download=m.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('copy-model').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(D.models[selected].deck);toast('選んだ完成BDFをコピーしました');}catch{toast('コピーできませんでした。BDF保存を使ってください');}});
 select('simple');theory();endFace();route();
})();
